/**
 * Tier-2 specialized aggregations — `countIf`, `sumIf`, `stringAgg`,
 * `stringAggUnique`. These have argument shapes that don't fit the
 * generic aggregation pattern in `index.ts`:
 *
 *   - `countIf` / `sumIf` accept a *predicate text* second argument
 *     (e.g. `'>30'`, `'<30'`, `'30'`). The EDK models this as a
 *     structured `Predicate` object — `{ op, value }` — so the
 *     comparison operator is a typed literal union rather than a
 *     free-form string. The serializer assembles the wire predicate
 *     text.
 *
 *   - `stringAgg` accepts a variadic `ORDER BY` clause embedded inside its
 *     separator argument on the wire. The EDK models that as
 *     `{ orderBy: [{ field, direction }, ...] }`; direction defaults to ASC.
 */
import type { ComposedExpr, ExprLike, ExprType } from "./types.js";
/** Discoverable comparison operators accepted by COUNTIF and SUMIF. */
export declare const predicateOp: {
    readonly equal: "=";
    readonly notEqual: "!=";
    readonly notEqualSql: "<>";
    readonly greaterThan: ">";
    readonly greaterThanOrEqual: ">=";
    readonly lessThan: "<";
    readonly lessThanOrEqual: "<=";
};
export type PredicateOp = (typeof predicateOp)[keyof typeof predicateOp];
/**
 * Predicate for `countIf` / `sumIf`. The operator defaults to `"="`
 * when omitted (matches the wire form: a bare value like `'30'` means
 * "equal to 30"). The value is stringified before quoting.
 */
export interface Predicate {
    readonly op?: PredicateOp;
    readonly value: string | number;
}
export type ErgonomicPredicate = {
    readonly equal: string | number;
} | {
    readonly notEqual: string | number;
} | {
    readonly greaterThan: string | number;
} | {
    readonly greaterThanOrEqual: string | number;
} | {
    readonly lessThan: string | number;
} | {
    readonly lessThanOrEqual: string | number;
};
export type PredicateInput = Predicate | ErgonomicPredicate;
/**
 * Count rows where `field` matches the predicate. Wire form:
 * `COUNTIF(field, 'predicate')` — the predicate is a quoted string
 * with the comparison operator prefix (e.g. `'>30'`) and value.
 */
export declare function countIf<const Field extends ExprLike<"text"> | ExprLike<"number"> | ExprLike<"decimal">>(field: Field, predicate: PredicateInput): ComposedExpr<"number", [Field]>;
/**
 * Sum rows of `field` where the value matches the predicate. Wire form:
 * `SUMIF(field, 'predicate')`. The output preserves the field's NUMBER or
 * DECIMAL brand.
 */
export declare function sumIf<const Field extends ExprLike<"number">>(field: Field, predicate: PredicateInput): ComposedExpr<"number", [Field]>;
export declare function sumIf<const Field extends ExprLike<"decimal">>(field: Field, predicate: PredicateInput): ComposedExpr<"decimal", [Field]>;
/** Discoverable sort directions for STRING_AGG's ORDER BY clause. */
export declare const orderByDirection: {
    readonly ascending: "ASC";
    readonly descending: "DESC";
};
export type OrderByDirection = (typeof orderByDirection)[keyof typeof orderByDirection];
export type ErgonomicOrderByDirection = "asc" | "desc";
/**
 * One ORDER BY term for `stringAgg`. The field can be any expression;
 * `stringAggUnique` has no ORDER BY grammar slot.
 */
export interface StringAggOrderBy {
    readonly field?: ExprLike<ExprType>;
    readonly value?: ExprLike<ExprType>;
    readonly direction?: OrderByDirection | ErgonomicOrderByDirection;
}
/** Typed options for STRING_AGG's optional, variadic ORDER BY clause. */
export interface StringAggOptions {
    readonly orderBy: readonly [StringAggOrderBy, ...StringAggOrderBy[]];
}
/**
 * Concatenate `field` values across related rows, separated by
 * `separator`. Optional `orderBy` controls row ordering.
 */
export declare function stringAgg<const Field extends ExprLike<"text">, const Separator extends ExprLike<"text">>(field: Field, separator: Separator, options?: StringAggOptions): ComposedExpr<"text", [Field, Separator]>;
/** Distinct-only variant of `stringAgg`. Server emits duplicates once. */
export declare function stringAggUnique<const Field extends ExprLike<"text">, const Separator extends ExprLike<"text">>(field: Field, separator: Separator): ComposedExpr<"text", [Field, Separator]>;
